1	// @vitest-environment node
2	/**
3	 * Rendered-layout regression for the UX-01 compact row (real Chrome, real CSS).
4	 *
5	 * This is the P1 guard for the compact conversation row at the 1000 CSS px
6	 * supported desktop breakpoint: with an unknown read state (and, in the worst
7	 * case, a pending membership operation) the row metadata was unbounded and
8	 * collapsed the subject/snippet column to zero width. jsdom has no layout, so
9	 * these assertions only mean something against real rendered CSS.
10	 *
11	 * The second P1 guard covers larger user text: at 1000px with the long old
12	 * date label, a 24px root font still fits inline (the sender column gives up
13	 * width first); from about 26px the full inline metadata no longer fits, so
14	 * the adaptive compact presentation collapses the actions behind a named,
15	 * keyboard- and pointer-operable disclosure (still without overflow at 28px
16	 * and 30px) instead of trading subject collapse for horizontal overflow.
17	 *
18	 * Opt-in only: set EMAIL_OS_RENDERED_LAYOUT_CHROME to a Chrome/Chromium binary
19	 * path to run, e.g.
20	 *
21	 *   EMAIL_OS_RENDERED_LAYOUT_CHROME=/path/to/chrome \
22	 *     mise run test:rendered
23	 *
24	 * The test starts its own ephemeral Vite dev server and its own headless
25	 * Chrome profile (synthetic in-memory browser fake only — never real Gmail,
26	 * never real mail), and tears both down in `afterAll`. Default `pnpm test`
27	 * the default test task excludes it.
28	 */
29	import { afterAll, beforeAll, describe, expect, it } from 'vitest';
30	import { startRenderedHarness, type RenderedHarness } from '../rendered/chromium';
31	
32	const chromePath = process.env.EMAIL_OS_RENDERED_LAYOUT_CHROME ?? '';
33	
34	interface Rect { left: number; right: number; top: number; bottom: number; width: number; height: number }
35	interface RowMeasure {
36	  innerWidth: number;
37	  clientMode: string | null;
38	  row: Rect;
39	  rowScrollWidth: number;
40	  rowClientWidth: number;
41	  listScrollWidth: number;
42	  listClientWidth: number;
43	  sender: Rect;
44	  subjectSnippet: Rect;
45	  subject: { left: number; right: number; width: number; visibleChars: number; truncated: boolean; text: string };
46	  meta: Rect;
47	  date: string | null;
48	  pending: { width: number; text: string } | null;
49	  readState: { width: number; text: string; test: string | null; label: string | null } | null;
50	  buttons: Array<{ name: string; test: string | null; visible: boolean } & Rect>;
51	  focusedButtons: Array<string | null>;
52	  toggle: { visible: boolean; ariaExpanded: string | null } & Rect | null;
53	  actionsPanel: { position: string; visibility: string; width: number } | null;
54	}
55	
56	describe.skipIf(chromePath === '')('InboxList rendered layout (real Chrome, opt-in)', () => {
57	  let harness: RenderedHarness | null = null;
58	  let cdp: RenderedHarness['cdp'];
59	
60	  beforeAll(async () => {
61	    harness = await startRenderedHarness(chromePath, 'email-os-layout-chrome-', new URL('../..', import.meta.url).pathname);
62	    cdp = harness.cdp;
63	  }, 120_000);
64	
65	  afterAll(async () => { await harness?.close(); });
66	
67	  /** Replaces the default shell with a fresh synthetic browser-fake app. */
68	  const MOUNT_SCRIPT = `(async () => {
69	  const vueUrl = performance.getEntriesByType('resource').map((x) => x.name).find((n) => n.includes('/node_modules/.vite/deps/vue.js'));
70	  if (!vueUrl) throw new Error('Vite Vue dep not found');
71	  const { createApp } = await import(vueUrl);
72	  const { default: App } = await import('/src/App.vue');
73	  const { createBrowserFakeMailClient } = await import('/src/lib/ipc/browser-fake.ts');
74	  window.__layoutMount = async (mode, options = {}) => {
75	    const root = document.querySelector('#app');
76	    root.__vue_app__?.unmount();
77	    const fake = createBrowserFakeMailClient();
78	    if (mode === 'gmail-actions') {
79	      fake.controls.setAccount({ mode: 'gmail', connection: 'connected', emailAddress: 'review@example.test', mutationAccess: 'enabled', coverageLimit: 100 });
80	    }
81	    window.__layoutFake = fake;
82	    // The long old-date label is the widest realistic trailing date.
83	    const client = options.oldDate
84	      ? { ...fake, listConversations: async () => {
85	          const snapshot = await fake.listConversations();
86	          return { ...snapshot, conversations: snapshot.conversations.map((r) => r.ref.conversationId === 'conv-01' || r.ref.conversationId === 'conv-17' ? { ...r, lastMessageAt: '2001-09-30T09:00:00Z' } : r) };
87	        } }
88	      : fake;
89	    createApp(App, { client, mode: 'browser-preview' }).mount(root);
90	  };
91	})()`;
92	
93	  const MEASURE_SCRIPT = `(() => {
94	  const row = document.querySelector('[data-test="conversation-row-conv-01"]');
95	  if (!row) throw new Error('conv-01 row missing');
96	  const rect = (el) => { const r = el.getBoundingClientRect(); return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height }; };
97	  const subject = row.querySelector('.row-subject');
98	  const textNode = subject.firstChild;
99	  const box = subject.getBoundingClientRect();
100	  // Range client rects are clipped by text-overflow: ellipsis, so they cannot
101	  // count hidden characters. caretRangeFromPoint walks the actually-rendered
102	  // prefix: the deepest text offset reachable inside the subject box is the
103	  // number of leading characters a reader can see.
104	  const midY = box.top + box.height / 2;
105	  let visibleChars = 0;
106	  for (const frac of [0.55, 0.7, 0.85, 0.95]) {
107	    const caret = document.caretRangeFromPoint(box.left + box.width * frac, midY);
108	    if (caret && caret.startContainer === textNode) visibleChars = Math.max(visibleChars, caret.startOffset);
109	  }
110	  const pick = (selector) => { const el = row.querySelector(selector); return el ? { width: el.getBoundingClientRect().width, text: el.textContent, test: el.getAttribute('data-test'), label: el.getAttribute('aria-label') } : null; };
111	  const isVisible = (el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
112	  const focusedButtons = [];
113	  for (const button of row.querySelectorAll('button')) {
114	    button.focus();
115	    if (document.activeElement === button) focusedButtons.push(button.getAttribute('data-test'));
116	  }
117	  const toggle = row.querySelector('[data-test^="row-actions-toggle-"]');
118	  const panel = row.querySelector('.row-actions');
119	  const panelStyle = panel ? getComputedStyle(panel) : null;
120	  return {
121	    innerWidth,
122	    clientMode: document.querySelector('.app')?.getAttribute('data-client-mode') ?? null,
123	    row: rect(row),
124	    rowScrollWidth: row.scrollWidth,
125	    rowClientWidth: row.clientWidth,
126	    listScrollWidth: document.querySelector('.inbox-scroll').scrollWidth,
127	    listClientWidth: document.querySelector('.inbox-scroll').clientWidth,
128	    sender: rect(row.querySelector('.row-sender')),
129	    subjectSnippet: rect(row.querySelector('.row-subject-snippet')),
130	    subject: { left: box.left, right: box.right, width: box.width, visibleChars, truncated: subject.scrollWidth > subject.clientWidth + 0.5, text: subject.textContent },
131	    meta: rect(row.querySelector('.row-meta')),
132	    date: row.querySelector('.row-time')?.textContent ?? null,
133	    pending: pick('[data-test="row-pending"]'),
134	    readState: pick('[data-test="row-read-unknown"], [data-test="row-read"], [data-test="row-unread"]'),
135	    buttons: [...row.querySelectorAll('button')].map((b) => ({ name: (b.getAttribute('aria-label') ?? b.textContent ?? '').trim(), test: b.getAttribute('data-test'), visible: isVisible(b), ...rect(b) })),
136	    focusedButtons,
137	    toggle: toggle ? { visible: isVisible(toggle), ariaExpanded: toggle.getAttribute('aria-expanded'), ...rect(toggle) } : null,
138	    actionsPanel: panel && panelStyle ? { position: panelStyle.position, visibility: panelStyle.visibility, width: panel.getBoundingClientRect().width } : null,
139	  };
140	})()`;
141	
142	  async function resize(width: number): Promise<void> {
143	    await cdp!.cmd('Emulation.setDeviceMetricsOverride', { width, height: 720, screenWidth: width, screenHeight: 720, deviceScaleFactor: 1, mobile: false });
144	    await tick();
145	  }
146	
147	  async function tick(): Promise<void> {
148	    await cdp!.js('new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
149	  }
150	
151	  async function mountGmailActions(options: { oldDate?: boolean } = {}): Promise<void> {
152	    // (Re)installs the mount helper (module imports are cached), then mounts.
153	    await cdp!.js(MOUNT_SCRIPT);
154	    await cdp!.js(`window.__layoutMount('gmail-actions', ${JSON.stringify(options)})`);
155	    await tick();
156	  }
157	
158	  /** Emulates a larger user root-font preference (never overrides it in the app). */
159	  async function setRootFont(fontPx: number | ''): Promise<void> {
160	    const value = fontPx === '' ? '' : `${fontPx}px`;
161	    await cdp!.js(`document.documentElement.style.fontSize = ${JSON.stringify(value)}`);
162	    await tick();
163	  }
164	
165	  async function measure(): Promise<RowMeasure> {
166	    return cdp!.js<RowMeasure>(MEASURE_SCRIPT);
167	  }
168	
169	  /** Real CDP key event (trusted input), not HTMLElement dispatch. */
170	  async function realKey(key: 'Tab' | 'Enter' | 'Escape'): Promise<void> {
171	    const virtualKey = key === 'Tab' ? 9 : key === 'Enter' ? 13 : 27;
172	    // Enter needs the carriage-return text payload for Chrome to run the
173	    // native button-activation default action on the trusted keydown.
174	    await cdp!.cmd('Input.dispatchKeyEvent', { type: 'keyDown', key, code: key, windowsVirtualKeyCode: virtualKey, ...(key === 'Enter' ? { text: '\r' } : {}) });
175	    await cdp!.cmd('Input.dispatchKeyEvent', { type: 'keyUp', key, code: key, windowsVirtualKeyCode: virtualKey });
176	    await tick();
177	  }
178	
179	  /** Real CDP mouse click at the center of a measured rect (trusted input). */
180	  async function realClick(r: Rect): Promise<void> {
181	    const x = r.left + r.width / 2;
182	    const y = r.top + r.height / 2;
183	    await cdp!.cmd('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y });
184	    await cdp!.cmd('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', buttons: 1, clickCount: 1 });
185	    await cdp!.cmd('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', buttons: 0, clickCount: 1 });
186	    await tick();
187	  }
188	
189	  function assertCompactRowLayout(m: RowMeasure, options: { minVisibleChars: number; expectPending: boolean; expectFullSubject?: boolean; expectCompact?: boolean }): void {
190	    // Synthetic-only guard: these numbers are meaningless outside the labelled preview.
191	    expect(m.clientMode).toBe('browser-preview');
192	    expect(m.innerWidth).toBeGreaterThanOrEqual(1000);
193	
194	    // The subject/snippet column never collapses; the subject itself keeps a
195	    // readable prefix of the fixture text visible ("Fixture thread …").
196	    expect(m.subjectSnippet.width).toBeGreaterThanOrEqual(120);
197	    expect(m.subject.width).toBeGreaterThanOrEqual(100);
198	    expect(m.subject.visibleChars).toBeGreaterThanOrEqual(options.minVisibleChars);
199	    expect(m.subject.text).toBe('Fixture thread 1: weekly status');
200	    if (options.expectFullSubject) {
201	      // Wide desktop sanity: the whole subject renders without truncation.
202	      expect(m.subject.truncated).toBe(false);
203	    }
204	
205	    // Single-line scanning rhythm, no horizontal overflow anywhere in the row.
206	    expect(m.row.height).toBeLessThanOrEqual(48);
207	    expect(m.rowScrollWidth).toBeLessThanOrEqual(m.rowClientWidth + 1);
208	    expect(m.listScrollWidth).toBeLessThanOrEqual(m.listClientWidth + 1);
209	
210	    const visibleButtons = m.buttons.filter((b) => b.visible);
211	    if (options.expectCompact) {
212	      // Adaptive compact presentation: the inline actions leave the flow behind
213	      // the named disclosure control — hidden, never clipped, still measurable.
214	      expect(m.toggle).not.toBeNull();
215	      expect(m.toggle!.visible).toBe(true);
216	      expect(m.toggle!.ariaExpanded).toBe('false');
217	      // The disclosure toggle is the only visible row action control.
218	      expect(visibleButtons.map((b) => b.test)).toEqual(['row-actions-toggle-conv-01']);
219	      expect(m.actionsPanel!.position).toBe('absolute');
220	      expect(m.actionsPanel!.visibility).toBe('hidden');
221	      expect(m.actionsPanel!.width).toBeGreaterThan(0);
222	    } else {
223	      // Expanded presentation: every action stays a visible, named,
224	      // keyboard-reachable control inside the row.
225	      expect(visibleButtons.length).toBeGreaterThan(0);
226	      for (const button of visibleButtons) {
227	        expect(button.width).toBeGreaterThan(0);
228	        expect(button.right).toBeLessThanOrEqual(m.row.right + 0.5);
229	        expect(button.name.length).toBeGreaterThan(0);
230	      }
231	      expect(m.actionsPanel!.visibility).toBe('visible');
232	      expect(m.focusedButtons).toHaveLength(visibleButtons.length);
233	    }
234	
235	    // Pending and read-state disclosures stay visible (not clipped away).
236	    if (options.expectPending) {
237	      expect(m.pending).not.toBeNull();
238	      expect(m.pending!.width).toBeGreaterThan(0);
239	      expect(m.pending!.text).toBe('Pending…');
240	    }
241	    // The unknown read state is a visible gutter glyph with an exact name.
242	    expect(m.readState).not.toBeNull();
243	    expect(m.readState!.width).toBeGreaterThan(0);
244	    expect(m.readState!.test).toBe('row-read-unknown');
245	    expect(m.readState!.label).toBe('Read state unknown');
246	  }
247	
248	  it('keeps a readable single-line subject with unknown read state, pending membership, and row actions', async () => {
249	    try {
250	      // Scenario 1: unknown read state, actions enabled, 1000 CSS px — the P1 case.
251	      await resize(1000);
252	      await setRootFont(16);
253	      await mountGmailActions();
254	      await cdp!.js("window.__layoutFake.controls.markReadUnknown('conv-01')");
255	      await tick();
256	      const unknown = await measure();
257	      assertCompactRowLayout(unknown, { minVisibleChars: 10, expectPending: false });
258	      // Actions enabled: directional read controls, Remind, and Archive stay
259	      // explicit, with their full accessible names on compact labels.
260	      expect(unknown.buttons.filter((b) => b.visible).map((b) => b.test)).toEqual([
261	        'row-mark-read-conv-01',
262	        'row-mark-unread-conv-01',
263	        'row-remind-conv-01',
264	        'row-archive-conv-01',
265	      ]);
266	      expect(unknown.buttons.filter((b) => b.visible).map((b) => b.name)).toEqual(['Mark read', 'Mark unread', 'Remind me on this device', 'Mark done']);
267	      // Pointer route works: a click really issues the read command.
268	      await cdp!.js("document.querySelector('[data-test=\"row-mark-read-conv-01\"]').click()");
269	      await tick();
270	      const operations = await cdp!.js<number>('window.__layoutFake.controls.activity().length');
271	      expect(operations).toBeGreaterThan(0);
272	
273	      // Scenario 2: worst case — unknown read state plus a held unarchive
274	      // (realistic unknown+pending combination, never a faked pending read).
275	      await mountGmailActions();
276	      await cdp!.js(`(async () => {
277	        const fake = window.__layoutFake;
278	        fake.controls.markReadUnknown('conv-01');
279	        fake.controls.behavior.hold = true;
280	        const snapshot = await fake.listConversations();
281	        const target = snapshot.conversations.find((r) => r.ref.conversationId === 'conv-01');
282	        await fake.setArchived({ conversation: target.ref, archived: false, requestId: 'layout-regression-held-unarchive' });
283	      })()`);
284	      await tick();
285	      const unknownPending = await measure();
286	      assertCompactRowLayout(unknownPending, { minVisibleChars: 10, expectPending: true });
287	      expect(unknownPending.buttons.filter((b) => b.visible).map((b) => b.name)).toEqual(['Mark read', 'Mark unread', 'Remind me on this device', 'Mark done']);
288	
289	      // Scenario 3: wider desktop sanity — nothing wedged, subject fully readable.
290	      await resize(1440);
291	      await mountGmailActions();
292	      await cdp!.js("window.__layoutFake.controls.markReadUnknown('conv-01')");
293	      await tick();
294	      const wide = await measure();
295	      assertCompactRowLayout(wide, { minVisibleChars: 20, expectPending: false, expectFullSubject: true });
296	      // Full fixture subject text fits (no truncation on a wide desktop); at
297	      // the 12px row type the whole fixture subject is ~172px wide.
298	      expect(wide.subject.width).toBeGreaterThan(150);
299	      // The sender column holds the 132px spec width on a wide list.
300	      expect(wide.sender.width).toBeGreaterThan(131.5);
301	      expect(wide.sender.width).toBeLessThanOrEqual(132.5);
302	    } finally {
303	      await setRootFont('').catch(() => undefined);
304	    }
305	  }, 180_000);
306	
307	  it('collapses overflowing row actions behind an operable disclosure at a larger root font', async () => {
308	    const setupScenario = async (rootFont: number): Promise<void> => {
309	      await resize(1000);
310	      await setRootFont(rootFont);
311	      await mountGmailActions({ oldDate: true });
312	      // Realistic unknown+pending membership: unknown read facts plus a held
313	      // unarchive (a pending read setter would make read facts known).
314	      await cdp!.js(`(async () => {
315	        const fake = window.__layoutFake;
316	        fake.controls.markReadUnknown('conv-01');
317	        fake.controls.markReadUnknown('conv-05');
318	        fake.controls.markReadUnknown('conv-17');
319	        fake.controls.behavior.hold = true;
320	        const snapshot = await fake.listConversations();
321	        for (const id of ['conv-01', 'conv-17']) {
322	          const target = snapshot.conversations.find((r) => r.ref.conversationId === id);
323	          await fake.setArchived({ conversation: target.ref, archived: false, requestId: 'larger-text-held-unarchive-' + id });
324	        }
325	      })()`);
326	      await tick();
327	    };
328	
329	    try {
330	      // 1000px / 16px root font, old date, unknown+pending: the expanded row
331	      // still fits, so the presentation and its stable action ids are unchanged.
332	      await setupScenario(16);
333	      const at16 = await measure();
334	      assertCompactRowLayout(at16, { minVisibleChars: 10, expectPending: true });
335	      expect(at16.date).toBe('30 Sep 2001');
336	      expect(at16.buttons.filter((b) => b.visible).map((b) => b.test)).toEqual([
337	        'row-mark-read-conv-01',
338	        'row-mark-unread-conv-01',
339	        'row-remind-conv-01',
340	        'row-archive-conv-01',
341	      ]);
342	      expect(at16.toggle!.visible).toBe(false);
343	
344	      // 1000px / 24px root font, same scenario: the sender column gives up
345	      // width first, so the expanded presentation still fits without any
346	      // collapse, overflow, or unreadable subject, and all four actions stay
347	      // visible. (Measured in the rendered harness at 1000px: the sender starts
348	      // shrinking at about 22px and reaches its 72px floor at about 25.5px;
349	      // the expanded row fits up to 25.5px and collapses from about 26px.
350	      // Since the Remind action and the 16px attachment glyph joined the row
351	      // the expanded step moved 30px → 24px; it was 20px before the rail/contact
352	      // layout pass. 24px is 1.5px below the collapse point with 25px of sender
353	      // width still to give.)
354	      await setRootFont(24);
355	      await tick();
356	      const at24 = await measure();
357	      assertCompactRowLayout(at24, { minVisibleChars: 10, expectPending: true });
358	      expect(at24.date).toBe('30 Sep 2001');
359	      expect(at24.buttons.filter((b) => b.visible).map((b) => b.test)).toEqual([
360	        'row-mark-read-conv-01',
361	        'row-mark-unread-conv-01',
362	        'row-remind-conv-01',
363	        'row-archive-conv-01',
364	      ]);
365	      expect(at24.toggle!.visible).toBe(false);
366	      expect(at24.sender.width).toBeLessThan(at16.sender.width);
367	
368	      // 1000px / 28px root font: the sender is giving up width and the
369	      // expanded presentation no longer fits, so the adaptive compact
370	      // presentation engages — subject stays readable, nothing clips or
371	      // overflows, and every action moves behind the named disclosure control.
372	      // (Collapse point at 1000px: 25.5px → 26px. Before the Remind action and
373	      // the attachment glyph it was about 33px; the old 34.5px compact step
374	      // overflows the row by 65px today, see the bound below.) 28px is 2.25px
375	      // below the compact-overflow point, with 31px of sender width to spare.
376	      //
377	      // Measured upper bound where even the compact row overflows (real Chrome
378	      // 156, synthetic fixture, old-date row with unknown read state and a
379	      // pending membership; overflow = row scrollWidth − clientWidth):
380	      //   1000px: compact fits up to 30.25px; 30.5px overflows by 3px, 31px by
381	      //           11px, 32px (200% of the default) by 27px, 34.5px by 65px.
382	      //   1100px: collapses at about 31.5px; compact fits up to 36.5px; 37px
383	      //           overflows by 4px, 38px by 20px.
384	      //   1280px: collapses at 39px (38px is still expanded); compact overflows by
385	      //           2px, 46px by 5px.
386	      // The sender and subject floors are the P1 readability guard and are not
387	      // traded for more headroom.
388	      await setRootFont(28);
389	      await tick();
390	      const at28 = await measure();
391	      assertCompactRowLayout(at28, { minVisibleChars: 10, expectPending: true, expectCompact: true });
392	      expect(at28.date).toBe('30 Sep 2001');
393	      // The sender gave up width before the actions collapsed (it may regain
394	      // a little of the width the collapse frees).
395	      expect(at28.sender.width).toBeLessThan(at16.sender.width);
396	      expect(at28.sender.width).toBeLessThan(115);
397	
398	      // 1000px / 30px root font, the failure this guard exists for: compact
399	      // presentation, disclosure operable by pointer and keyboard, no overflow.
400	      // (Compact fits up to 30.25px here, so this step keeps about 1px of
401	      // sender width above its 72px floor: it is the last step that fits.)
402	      await setRootFont(30);
403	      await tick();
404	      const at30 = await measure();
405	      assertCompactRowLayout(at30, { minVisibleChars: 10, expectPending: true, expectCompact: true });
406	      expect(at30.date).toBe('30 Sep 2001');
407	      expect(at30.sender.width).toBeLessThan(at16.sender.width);
408	      await realClick(at30.toggle!);
409	      const open30 = await measure();
410	      expect(open30.toggle!.ariaExpanded).toBe('true');
411	      expect(open30.actionsPanel!.visibility).toBe('visible');
412	      await realKey('Escape');
413	      const closed30 = await cdp!.js<string | null>("document.querySelector('[data-test=\"row-actions-toggle-conv-01\"]').getAttribute('aria-expanded')");
414	      expect(closed30).toBe('false');
415	
416	      // The pointer and keyboard sequence below runs at 28px, clearly inside
417	      // the range where the compact row fits.
418	      await setRootFont(28);
419	      await tick();
420	      const at28Again = await measure();
421	      expect(at28Again.toggle!.visible).toBe(true);
422	
423	      // Pointer access: a real CDP mouse click on the disclosure toggle opens
424	      // the row action panel.
425	      await realClick(at28Again.toggle!);
426	      const openByPointer = await measure();
427	      expect(openByPointer.toggle!.ariaExpanded).toBe('true');
428	      expect(openByPointer.actionsPanel!.visibility).toBe('visible');
429	      const popoverButtons = openByPointer.buttons.filter((b) => b.visible && b.test !== 'row-actions-toggle-conv-01');
430	      expect(popoverButtons.map((b) => b.name)).toEqual(['Mark read', 'Mark unread', 'Remind me on this device', 'Mark done']);
431	      // Every disclosed action is hit-testable at its center — inside the
432	      // visible panel, not clipped by the row or the list scroller. The hit
433	      // may be the button's own glyph or label, which activates the button.
434	      const hitTests = await cdp!.js<Array<{ test: string | null; hitIsTarget: boolean }>>(`[...document.querySelectorAll('[data-test="conversation-row-conv-01"] button')]
435	        .filter((b) => b.getAttribute('data-test') !== 'row-actions-toggle-conv-01' && b.getClientRects().length > 0 && getComputedStyle(b).visibility !== 'hidden')
