  const client = noRows ? { ...fake, listConversations: async () => ({ conversations: [], activity: [] }) } : fake;
  wrapper = mountApp(client, 'browser-preview', { attachTo: document.body });
  await flushPromises(); await flushMacrotasks(2); await flushPromises();
  return { fake, w: wrapper };
}
const none = { connection: 'disconnected', emailAddress: null, cachedConversations: 0, initialSyncComplete: false } as const;

