  min-width: 0;
  margin: 0 12px 0 0;
"""
new3=""".header-note {
  flex: 0 1 auto;
  min-width: 0;
  margin: -4px 12px -4px 0;
  padding-block: 4px;
"""
assert old3 in s
s=s.replace(old3,new3,1)
open(p,'w').write(s)
